	@Test
	void preservesValidPrefixWhenCorruptionChangesValueKind() throws Exception {
		writeCorruptTail();
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config())) {
			ValueStoreWalReader.ScanResult scan = reader.scan();
			assertThat(scan.records()).extracting(ValueStoreWalRecord::id).containsExactly(1);
			assertThat(scan.lastValidLsn()).isEqualTo(1);
			assertThat(scan.complete()).isFalse();
		}
	}

