	@Test
	void rejectsMalformedUtf8EvenWhenFrameChecksumMatches() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		writeFrame(output, "{\"t\":\"V\",\"ver\":1,\"segment\":1,\"firstId\":1}");
		ByteArrayOutputStream payload = new ByteArrayOutputStream();
		payload.writeBytes("{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"L\",\"lex\":\"".getBytes(StandardCharsets.UTF_8));
		payload.write(0xc3);
		payload.write('('); // 0x28 cannot continue the UTF-8 sequence beginning with 0xc3.
		payload.writeBytes("\"}".getBytes(StandardCharsets.UTF_8));
		writeFrame(output, payload.toByteArray());
		Files.write(directory.resolve("wal-1.v1"), output.toByteArray());
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config())) {
			ValueStoreWalReader.ScanResult scan;
			try {
				scan = reader.scan();
			} catch (JacksonException | IOException rejected) {
				// A decoding failure also correctly rejects the malformed frame.
				return;
			}
			assertThat(scan.records()).as("Malformed UTF-8 must not produce an altered lexical value").isEmpty();
			assertThat(scan.complete()).isFalse();
		}
	}

